def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    coins from `coins`. If impossible, return -1.
    """
    # Edge case
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Remove non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array where dp[i] is min coins to make i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

