import math

def solve(n):
    # Count primes strictly less than n.
    if isinstance(n, float):
        if n != n or n in (float('inf'), float('-inf')):
            raise ValueError("n must be a finite integer")
        if not n.is_integer():
            n = math.floor(n) + 1  # primes < n  ==  primes < floor(n)+1
        else:
            n = int(n)
    if n <= 2:
        return 0
    # Odd-only sieve: index i represents the odd number 2*i + 1.
    size = (n + 1) // 2
    sieve = bytearray([1]) * size
    sieve[0] = 0  # 1 is not prime
    limit = math.isqrt(n - 1)
    for i in range(1, (limit // 2) + 1):
        if sieve[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            if start < size:
                sieve[start::p] = bytearray(len(range(start, size, p)))
    return 1 + sieve.count(1)  # +1 accounts for the only even prime, 2

