def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers '()', '[]', '{}' only, ignoring other characters.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Returns the canonical path.
    """
    # Split by '/', ignore empty components caused by leading/trailing/multiple slashes
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # skip empty and current directory
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root, ignore
        else:
            stack.append(part)
    # Construct result
    result = '/' + '/'.join(stack)
    return result if result != '' else '/'

