{"task_id": "T21", "code": "def solve(weights, values, capacity):
    """0/1 knapsack returning the maximum total value.
    Handles zero-weight items (always take them) and guards against
    negative capacities or negative weights by ignoring such items.
    """
    # Guard invalid capacity
    if capacity <= 0:
        # Only zero-weight items can be taken
        zero_val = 0
        for w, v in zip(weights, values):
            if w == 0:
                zero_val += v
        return zero_val
    # Ensure equal length processing
    n = min(len(weights), len(values))
    zero_val = 0
    items = []  # (weight, value) for positive weight items
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w == 0:
            zero_val += v
        elif w > 0:
            items.append((w, v))
        # ignore items with non‑positive weight (w < 0) as they are not standard
    dp = [0] * (capacity + 1)
    for w, v in items:
        # iterate backwards to enforce 0/1 usage
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity] + zero_val"}

