def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Resolves '.' and '..', collapses duplicate slashes, strips whitespace-only components,
    and ensures no trailing slash (except root)."""
    stack = []
    for part in path.split('/'):
        part = part.strip()
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

def solve(lst):
    """Flatten a nested list (or tuple) of integers to a flat list preserving order.
    Non-integer, non-iterable elements are ignored.
    """
    result = []
    # Use a stack of iterators for depth-first left-to-right traversal.
    stack = [iter(lst)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, (list, tuple)):
            # Dive into this iterable before continuing current iterator.
            stack.append(iter(item))
        elif isinstance(item, int):
            result.append(item)
        # ignore other types
    return result

