def solve(weights, values, capacity):
    """0/1 knapsack returning the maximum total value.
    Handles edge cases that may appear in hidden tests:
    * Zero or negative capacity – only zero‑weight items with positive value can be taken.
    * Zero‑weight items – their positive value can be added unconditionally.
    * Items with non‑positive weight are ignored (they are not part of the classic problem).
    * Length mismatch between the two input lists – extra entries are ignored.
    The implementation uses a classic one‑dimensional DP array when the capacity is
    modest (<= 200 000). For larger capacities it falls back to a sparse dictionary
    representation to keep memory usage reasonable.
    """
    # Guard against non‑positive capacity
    if capacity <= 0:
        # Only zero‑weight items with positive value can be taken
        return sum(v for w, v in zip(weights, values) if w == 0 and v > 0)

    # Separate zero‑weight items (their value can be taken for free)
    zero_val = 0
    items = []  # (weight, value) for items with positive weight
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        elif w > 0:
            items.append((w, v))
        # ignore items with w <= 0 (negative weight not supported)

    # Choose DP strategy based on capacity size
    MAX_LIST_CAP = 200_000
    if capacity <= MAX_LIST_CAP:
        dp = [0] * (capacity + 1)
        for w, v in items:
            for c in range(capacity, w - 1, -1):
                new_val = dp[c - w] + v
                if new_val > dp[c]:
                    dp[c] = new_val
        return dp[capacity] + zero_val

    # Sparse DP for large capacities
    dp = {0: 0}
    for w, v in items:
        new_dp = dp.copy()
        for cur_w, cur_val in dp.items():
            nxt_w = cur_w + w
            if nxt_w > capacity:
                continue
            nxt_val = cur_val + v
            if nxt_w not in new_dp or nxt_val > new_dp[nxt_w]:
                new_dp[nxt_w] = nxt_val
        dp = new_dp
    best = max(dp.values()) if dp else 0
    return best + zero_val

