def solve(n):
    """Return the number of primes strictly below n."""
    if n <= 2:
        return 0
    sieve = bytearray([1]) * n
    sieve[0] = sieve[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n:step] = bytearray(len(range(start, n, step)))
    return sum(sieve)

