def solve(weights, values, capacity):
    """0/1 knapsack.
    - Only items with weight > 0 are considered (weights <= 0 are ignored).
    - If capacity is less than 0, treat it as 0.
    - Length mismatch: iterate up to the shorter list.
    """
    if capacity <= 0:
        return 0
    n = min(len(weights), len(values))
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w <= 0:
            continue
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

