def solve(weights, values, capacity):
    """0/1 knapsack returning max total value.
    Handles edge cases:
    * capacity may be zero or negative.
    * zero-weight items with positive value are always taken.
    * items with non‑positive weight are ignored.
    * input lists may have different lengths; extra elements are ignored.
    Uses a sparse DP (dictionary) to avoid large memory usage.
    """
    # Sum values of zero-weight items (only if positive)
    zero_val = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        elif w > 0:
            items.append((w, v))
        # ignore w <= 0 (negative weight) as not standard
    if capacity <= 0:
        # Only zero‑weight items can be taken
        return zero_val
    # Sparse DP: mapping weight -> max value achievable
    dp = {0: 0}
    for w, v in items:
        # iterate over a snapshot of current states
        current = list(dp.items())
        for cur_w, cur_val in current:
            nxt_w = cur_w + w
            if nxt_w > capacity:
                continue
            nxt_val = cur_val + v
            if nxt_w not in dp or nxt_val > dp[nxt_w]:
                dp[nxt_w] = nxt_val
    best = max(dp.values()) if dp else 0
    return best + zero_val

