def solve(s):
    """Run-length encode a string: 'aaab' -> 'a3b1'.
    Each maximal run of repeated characters is emitted as the character
    followed by the length of the run.
    """
    if not s:
        return ''
    out = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(prev + str(count))
            prev = ch
            count = 1
    out.append(prev + str(count))
    return ''.join(out)

