def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Resolves '.' and '..', collapses duplicate slashes, and ignores any whitespace-only components.
    Returns '/' for the root.
    """
    stack = []
    for part in path.split('/'):
        part = part.strip()
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

