    """Flatten a nested list (or tuple) of integers, including booleans as integers.
    Returns a flat list preserving left‑to‑right order.
    """
    result = []
    # Use a stack of iterators for depth‑first left‑to‑right traversal.
    # If lst is not iterable (e.g., an int), treat it as a single element.
    try:
        stack = [iter(lst)]
    except TypeError:
        return [lst] if isinstance(lst, int) else []
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, (list, tuple)):
            stack.append(iter(item))
        elif isinstance(item, int):  # includes bool
            result.append(item)
        # ignore other types
    return result

