def solve(words):
    # Group anagrams by sorted-character signature; each group sorted
    # alphabetically, groups ordered by their signature.
    groups = {}
    for w in words:
        key = ''.join(sorted(w))
        groups.setdefault(key, []).append(w)
    res = [sorted(g) for g in groups.values()]
    res.sort()
    return res

