def solve(weights, values, capacity):
    """0/1 knapsack returning max total value.
    Handles edge cases:
    * capacity may be zero or negative – zero-weight positive-value items are still usable.
    * zero-weight items with positive value are always taken (they don't consume capacity).
    * items with non‑positive weight are ignored.
    * lists may have different lengths – extra entries are ignored.
    Uses a sparse DP (dictionary) to stay memory‑efficient for large capacities.
    """
    # Gather zero‑weight items with positive value
    zero_val = 0
    items = []  # (weight, value) for weight>0
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        elif w > 0:
            items.append((w, v))
        # ignore non‑positive weight items
    # If capacity is non‑positive, cannot take any positive‑weight items
    if capacity <= 0:
        return zero_val
    # Sparse DP: weight -> best value
    dp = {0: 0}
    for w, v in items:
        current = list(dp.items())
        for cur_w, cur_val in current:
            nxt_w = cur_w + w
            if nxt_w > capacity:
                continue
            nxt_val = cur_val + v
            if nxt_w not in dp or nxt_val > dp[nxt_w]:
                dp[nxt_w] = nxt_val
    best = max(dp.values()) if dp else 0
    return best + zero_val

