    # Normalize capacity
    if capacity < 0:
        capacity = 0
    # Separate zero‑weight positive‑value items
    zero_val = 0
    items = []  # (weight, value) with weight > 0
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        elif w > 0:
            items.append((w, v))
        # ignore w <= 0 (negative weight) as they are not part of standard knapsack
    # DP array
    dp = [0] * (capacity + 1)
    for w, v in items:
