def solve(path):
    """Simplify a Unix-style file path.
    Works for absolute paths (starting with '/') and relative paths.
    Resolves '.' and '..', collapses redundant slashes, and removes any trailing slash
    unless the result is the root '/' for absolute paths or an empty string for relative.
    """
    is_absolute = path.startswith('/')
    # Split on '/', keep empty strings to handle leading/trailing slashes
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # For relative paths, keep leading '..'
                if not is_absolute:
                    stack.append('..')
        else:
            stack.append(part)
    if is_absolute:
        return '/' + '/'.join(stack) if stack else '/'
    else:
